import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"51、【震】 震下震上","description":"溫公易說 - 51、【震】 震下震上","frontmatter":{"title":"51、【震】 震下震上","description":"溫公易說 - 51、【震】 震下震上"},"headers":[],"relativePath":"classics/wengong/052.md","filePath":"classics/wengong/052.md"}'),l={name:"classics/wengong/052.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_51、【震】-震下震上" tabindex="-1">51、【震】 震下震上 <a class="header-anchor" href="#_51、【震】-震下震上" aria-label="Permalink to “51、【震】 震下震上”">​</a></h1><h3 id="彖曰-震-亨。震來虩虩-恐致福也。笑言啞啞-後有則也。震驚百里-驚逺而懼邇也。出可以守宗廟社稷-以為祭主也。" tabindex="-1">彖曰：震，亨。震來虩虩，恐致福也。笑言啞啞，後有則也。震驚百里，驚逺而懼邇也。出可以守宗廟社稷，以為祭主也。 <a class="header-anchor" href="#彖曰-震-亨。震來虩虩-恐致福也。笑言啞啞-後有則也。震驚百里-驚逺而懼邇也。出可以守宗廟社稷-以為祭主也。" aria-label="Permalink to “彖曰：震，亨。震來虩虩，恐致福也。笑言啞啞，後有則也。震驚百里，驚逺而懼邇也。出可以守宗廟社稷，以為祭主也。”">​</a></h3><p>震驚百里，不喪匕鬯，夫主大器者，不可以無威也。無威則民不服，民不服則所守喪矣。故曰震驚百里，不喪匕鬯。</p><h3 id="象曰-洊雷-震。君子以恐懼修省。" tabindex="-1">象曰：洊雷，震。君子以恐懼修省。 <a class="header-anchor" href="#象曰-洊雷-震。君子以恐懼修省。" aria-label="Permalink to “象曰：洊雷，震。君子以恐懼修省。”">​</a></h3><h3 id="初九-震來虩虩-後笑言啞啞-吉-象曰-震來虩虩-恐致福也。笑言啞啞-後有則也。" tabindex="-1">初九：震來虩虩，後笑言啞啞，吉 象曰：震來虩虩，恐致福也。笑言啞啞，後有則也。 <a class="header-anchor" href="#初九-震來虩虩-後笑言啞啞-吉-象曰-震來虩虩-恐致福也。笑言啞啞-後有則也。" aria-label="Permalink to “初九：震來虩虩，後笑言啞啞，吉 象曰：震來虩虩，恐致福也。笑言啞啞，後有則也。”">​</a></h3><h3 id="六二-震來厲-億喪貝-躋於九陵-勿逐-七日得-象曰-震來厲-乘剛也。" tabindex="-1">六二：震來厲，億喪貝，躋於九陵，勿逐，七日得 象曰：震來厲，乘剛也。 <a class="header-anchor" href="#六二-震來厲-億喪貝-躋於九陵-勿逐-七日得-象曰-震來厲-乘剛也。" aria-label="Permalink to “六二：震來厲，億喪貝，躋於九陵，勿逐，七日得 象曰：震來厲，乘剛也。”">​</a></h3><h3 id="六三-震蘇蘇-震行無眚-象曰-震蘇蘇-位不當也。" tabindex="-1">六三：震蘇蘇，震行無眚 象曰：震蘇蘇，位不當也。 <a class="header-anchor" href="#六三-震蘇蘇-震行無眚-象曰-震蘇蘇-位不當也。" aria-label="Permalink to “六三：震蘇蘇，震行無眚 象曰：震蘇蘇，位不當也。”">​</a></h3><h3 id="九四-震遂泥-象曰-震遂泥-未光也。" tabindex="-1">九四：震遂泥 象曰：震遂泥，未光也。 <a class="header-anchor" href="#九四-震遂泥-象曰-震遂泥-未光也。" aria-label="Permalink to “九四：震遂泥 象曰：震遂泥，未光也。”">​</a></h3><p>泥者以陽居陰，喪其威也。</p><h3 id="六五-震往來厲-億無喪-有事-象曰-震往來厲-危行也。" tabindex="-1">六五：震往來厲，億無喪，有事 象曰：震往來厲，危行也。 <a class="header-anchor" href="#六五-震往來厲-億無喪-有事-象曰-震往來厲-危行也。" aria-label="Permalink to “六五：震往來厲，億無喪，有事 象曰：震往來厲，危行也。”">​</a></h3><p>其事在中，大無喪也。</p><h3 id="上六-震索索-視矍矍-徵兇。震不於其躬-於其鄰-無咎。婚媾有言-象曰-震索索-中未得也。雖兇無咎-畏鄰戒也。" tabindex="-1">上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言 象曰：震索索，中未得也。雖兇無咎，畏鄰戒也。 <a class="header-anchor" href="#上六-震索索-視矍矍-徵兇。震不於其躬-於其鄰-無咎。婚媾有言-象曰-震索索-中未得也。雖兇無咎-畏鄰戒也。" aria-label="Permalink to “上六：震索索，視矍矍，徵兇。震不於其躬，於其鄰，無咎。婚媾有言 象曰：震索索，中未得也。雖兇無咎，畏鄰戒也。”">​</a></h3><p>震不於其躬，於其鄰者，禍在彼而思在此也。楚人滅江，秦穆公為之降服。出次不舉，過數曰：吾自懼也。君子曰：詩云“惟彼二國，其政不獲。惟此四國，爰究爰度。”其秦穆公之謂矣。</p>',13)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
